<script setup lang="ts">
import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import AccountDetails from '../../Components/AccountDetails.vue';import FinanceEditor from '../../Components/FinanceEditor.vue';import TransactionDetails from '../../Components/TransactionDetails.vue';import ConnectionDetails from '../../Components/ConnectionDetails.vue';import Modal from '../../Components/Modal.vue';import HistoryPanel from '../../Components/HistoryPanel.vue';import Pagination from '../../Components/Pagination.vue';import {json} from '../../lib/format';
const props=defineProps<{detail:any;catalog:any}>();
const editor=ref<any>(),transaction=ref<string>(),connection=ref<string>(),history=ref<any>(),error=ref('');
function edit(kind:string,record:any){if(kind==='account'&&record.type==='loan'&&record.loan_id){router.visit('/loans?loan='+record.loan_id+'&show_paid=1');return;}editor.value={kind,record};}
function openPayment(id:string){router.visit('/home?occurrence='+id);}
async function showHistory(type:string,id:string,url?:string){try{history.value=await json(url||'/history/'+type+'/'+id);}catch(e:any){error.value=e.message;}}
</script>
<template><AppLayout section="accounts"><Head :title="detail.account.name"/><Link href="/accounts" class="help hover:underline">Accounts /</Link><div class="mb-5 mt-2 flex flex-wrap items-center justify-between gap-3"><div><h1>{{detail.account.name}}</h1><p class="mt-2 text-muted">{{detail.account.institution_name||detail.account.type.replaceAll('_',' ')}}</p></div><div class="flex flex-wrap gap-2"><button class="btn" @click="edit('account',{...detail.account,loan_id:detail.loan_id,limit_cents:detail.limits.find((limit:any)=>limit.effective_date<=new Date().toISOString().slice(0,10))?.limit_cents,generated_schedules:detail.generated_schedules})">Edit details</button><template v-if="detail.account.source==='manual'&&detail.account.type!=='loan'"><button class="btn" @click="edit('balance',detail.account)">Update balance</button><button class="btn-primary" @click="edit('transaction',{account_id:detail.account.id})">Add transaction</button></template><button class="btn" @click="showHistory('accounts',detail.account.id)">Change history</button><button v-if="detail.account.type!=='loan'" class="link-danger" @click="editor={kind:'delete',record:detail.account,endpoint:'/accounts/'+detail.account.id}">Delete account</button></div></div>
<p v-if="error" role="alert" class="mb-5 text-warning">{{error}} <button class="underline" @click="showHistory('accounts',detail.account.id)">Try again</button></p>
<AccountDetails embedded :id="detail.account.id" :initial-detail="detail" :catalog="catalog" @edit="edit" @transaction="id=>transaction=id" @connection="id=>connection=id"/>
<FinanceEditor v-if="editor" :key="editor.kind+(editor.record?.id||'new')" v-bind="editor" :catalog="catalog" @close="editor=undefined"/>
<TransactionDetails v-if="transaction" :id="transaction" :catalog="catalog" @close="transaction=undefined" @edit="record=>{transaction=undefined;edit('transaction',record);}" @remove="record=>{transaction=undefined;editor={kind:'delete',record,endpoint:'/transactions/'+record.id};}" @history="id=>{transaction=undefined;showHistory('transactions',id);}" @payment="openPayment"/>
<ConnectionDetails v-if="connection" :id="connection" :catalog="catalog" @close="connection=undefined"/>
<Modal v-if="history" :open="true" title="Change history" @close="history=undefined"><div class="p-6"><HistoryPanel :events="history.data"/><Pagination :records="history" asynchronous @load="url=>showHistory('accounts',detail.account.id,url)"/></div></Modal>
</AppLayout></template>
